const fs = require('fs'); const h = require('./h.cjs');
const base = process.env.LINKDIR || '.'; const d = `${base}/w-lnk`; fs.rmSync(d, { recursive: true, force: true }); fs.mkdirSync(d, { recursive: true });
fs.writeFileSync(`${d}/a`, 'one/');
h.t('linkSync', () => fs.linkSync(`${d}/a`, `${d}/b`));
h.t('nlink', () => [fs.statSync(`${d}/a`).nlink, fs.statSync(`${d}/b`).nlink, fs.statSync(`${d}/a`).ino === fs.statSync(`${d}/b`).ino]);
h.t('shared write', () => { fs.appendFileSync(`${d}/a`, 'two/'); return fs.readFileSync(`${d}/b`, 'utf8'); });
